document.querySelectorAll('[data-lab="CP13-I1"]').forEach(root=>{
 const z=root.dataset.lang==='zh',q=s=>root.querySelector('[data-field="'+s+'"]');function draw(){const lam=+q('lambda').value,init=+q('initial').value,rate=+q('rate').value,s=+q('shear').value,rad=Math.PI/180,dt=.01,rhs=a=>.5*(lam*Math.cos(2*a)-1);let angle=init*rad;const states=[angle];for(let i=1;i<=4000;i++){const k1=rhs(angle),k2=rhs(angle+dt*k1/2),k3=rhs(angle+dt*k2/2),k4=rhs(angle+dt*k3);angle+=dt*(k1+2*k2+2*k3+k4)/6;states.push(angle);}const idx=Math.round(s/dt),now=states[idx],wrapped=((now/rad)%180+180)%180;const low=Math.floor(Math.min(...states)/rad/90)*90,high=Math.max(low+90,Math.ceil(Math.max(...states)/rad/90)*90),xp=v=>85+460*v/40,yp=v=>690-245*(v-low)/(high-low);
 q('lv').textContent=lam.toFixed(2);q('iv').textContent=init.toFixed(0);q('rv').textContent=rate.toFixed(1);q('sv').textContent=s.toFixed(1);let out='<rect width="600" height="790" fill="#f4f3ed"/><g font-family="Arial,sans-serif" font-size="22" fill="#173e45"><text x="28" y="35">'+(z?'当前指向矢；灰箭头为流向':'Current director; grey arrow shows flow')+'</text><path d="M90 190 H520 M500 178 L520 190 L500 202" stroke="#9aafaf" stroke-width="3" fill="none"/><circle cx="300" cy="190" r="110" stroke="#c5d4d0" fill="none" stroke-width="2"/>';
 out+='<line x1="'+(300-105*Math.cos(now))+'" y1="'+(190+105*Math.sin(now))+'" x2="'+(300+105*Math.cos(now))+'" y2="'+(190-105*Math.sin(now))+'" stroke="#207d80" stroke-width="10" stroke-linecap="round"/><text x="160" y="340">θ = '+wrapped.toFixed(2)+'° (mod 180°)</text><text x="28" y="393">'+(z?'累计角度 / °':'Unwrapped angle / °')+'</text><path d="M85 430 V690 H550" stroke="#496970" stroke-width="2" fill="none"/>';
 [low,(low+high)/2,high].forEach(v=>{out+='<text x="75" y="'+(yp(v)+7)+'" text-anchor="end">'+v.toFixed(0)+'</text>';});[0,10,20,30,40].forEach(v=>{out+='<text x="'+(xp(v)-10)+'" y="725">'+v+'</text>';});let d='';for(let i=0;i<=4000;i+=10)d+=(i?'L':'M')+xp(i*dt).toFixed(2)+','+yp(states[i]/rad).toFixed(2)+' ';out+='<path d="'+d+'" fill="none" stroke="#207d80" stroke-width="3"/><circle cx="'+xp(s)+'" cy="'+yp(now/rad)+'" r="7" fill="#bb6a38"/><text x="270" y="773">'+(z?'累计剪切量 s':'Accumulated shear s')+'</text></g>';q('plot').innerHTML=out;
 let regime;if(lam>1){const stable=.5*Math.acos(1/lam)/rad;regime=z?'稳定轴向角 '+stable.toFixed(2)+'°。':'Stable axial angle '+stable.toFixed(2)+'°.';}else if(lam<1){const period=2*Math.PI/(rate*Math.sqrt(1-lam*lam));regime=z?'持续翻滚，轴向周期 '+period.toFixed(3)+' s。':'Continuous tumbling; director period '+period.toFixed(3)+' s.';}else regime=z?'λ = 1：边界情形，接近取向时越来越慢，无有限翻滚周期。':'λ = 1: marginal case, slowing toward alignment with no finite tumbling period.';
 q('feedback').textContent=z?'物理时间 t = '+(s/rate).toFixed(3)+' s；累计角度 '+(now/rad).toFixed(2)+'°；轴向角 '+wrapped.toFixed(2)+'°。'+regime+' 曲线显示0到40的完整计算路径，圆点为当前观察位置。':'Physical time t = '+(s/rate).toFixed(3)+' s; unwrapped angle '+(now/rad).toFixed(2)+'°; axial angle '+wrapped.toFixed(2)+'°. '+regime+' The trace shows the full computed path from 0 to 40; the point marks the current observation.';
 }['lambda','initial','rate','shear'].forEach(k=>q(k).addEventListener('input',draw));draw();
});
